python3 << 'PYEOF'
import json

with open("/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-7-projects-gen-depth-contamination--claude-sessions-reviewer-08f7237f/51eb88ba-e52c-46f6-bfa0-e0d3c2871b77/tool-results/mcp-agent-ml-research-read_registry-1779483648310.txt", "r") as f:
    raw = json.load(f)

inner = json.loads(raw["result"]) if isinstance(raw.get("result"), str) else raw
experiments = inner["data"]["experiments"]

rows = []

for exp_id, exp in experiments.items():
    spec = exp.get("spec", {}) or {}
    metrics = exp.get("metrics", {}) or {}
    conclusion = exp.get("conclusion", "")
    status = exp.get("status", "")
    notes = exp.get("notes", "")
    exp_str = json.dumps(exp)

    # model
    model_name = spec.get("model_name", spec.get("model", spec.get("generator", "")))
    if not model_name:
        for k in ["base_model", "target_model"]:
            if k in spec:
                model_name = spec[k]
                break

    # scorer - check multiple places
    scorer = spec.get("scorer", spec.get("scorer_model", ""))
    if not scorer and isinstance(metrics.get("scorer"), str):
        scorer = metrics["scorer"]

    # AUC extraction - handle ALL formats
    auc_0v1, auc_1v2, auc_2v3 = None, None, None
    k_star = None

    # Format 1: top-level AUC_XvY or auc_XvY
    for prefix in ["AUC_", "auc_"]:
        if auc_0v1 is None and f"{prefix}0v1" in metrics:
            auc_0v1 = metrics[f"{prefix}0v1"]
        if auc_1v2 is None and f"{prefix}1v2" in metrics:
            auc_1v2 = metrics[f"{prefix}1v2"]
        if auc_2v3 is None and f"{prefix}2v3" in metrics:
            auc_2v3 = metrics[f"{prefix}2v3"]

    # Format 2: pairwise_auc dict
    if "pairwise_auc" in metrics and isinstance(metrics["pairwise_auc"], dict):
        pa = metrics["pairwise_auc"]
        if auc_0v1 is None and "0v1" in pa:
            auc_0v1 = pa["0v1"]
        if auc_1v2 is None and "1v2" in pa:
            auc_1v2 = pa["1v2"]
        if auc_2v3 is None and "2v3" in pa:
            auc_2v3 = pa["2v3"]

    # Format 3: dict with mean/std/folds
    def extract_mean(v):
        if isinstance(v, dict) and "mean" in v:
            return v["mean"]
        if isinstance(v, (int, float)):
            return v
        return None

    if auc_0v1 is not None:
        auc_0v1 = extract_mean(auc_0v1) if isinstance(auc_0v1, dict) else auc_0v1
    if auc_1v2 is not None:
        auc_1v2 = extract_mean(auc_1v2) if isinstance(auc_1v2, dict) else auc_1v2
    if auc_2v3 is not None:
        auc_2v3 = extract_mean(auc_2v3) if isinstance(auc_2v3, dict) else auc_2v3

    # K*
    for k in ["K_star", "k_star", "K*", "K_star_lower_bound"]:
        if k in metrics:
            k_star = metrics[k]
            if k == "K_star_lower_bound":
                k_star = f">={k_star}"
            break

    # scorer mentions
    scorer_notes = []
    if "self-scor" in exp_str.lower() or "self_scor" in exp_str.lower():
        scorer_notes.append("self")
    if "cross-scor" in exp_str.lower() or "cross_scor" in exp_str.lower() or "crossscorer" in exp_id.lower():
        scorer_notes.append("cross")

    if auc_0v1 is not None or auc_1v2 is not None:
        rows.append({
            "exp_id": exp_id,
            "model": str(model_name)[:40] if model_name else "",
            "scorer": str(scorer)[:25] if scorer else "",
            "k_star": k_star,
            "auc_0v1": auc_0v1,
            "auc_1v2": auc_1v2,
            "auc_2v3": auc_2v3,
            "status": status,
            "conclusion": conclusion,
            "scorer_notes": "/".join(scorer_notes),
        })

# Also add DeBERTa upperbound sub-entries
dub = experiments.get("exp_deberta_upperbound", {}).get("metrics", {})
for sub_key in ["wiki_pythia", "wiki_olmo", "wiki_qwen7b", "wiki_llama8b", "wiki_mistral7b"]:
    if sub_key in dub and isinstance(dub[sub_key], dict):
        d = dub[sub_key]
        rows.append({
            "exp_id": f"exp_deberta_upperbound/{sub_key}",
            "model": f"DeBERTa-v3 ({sub_key})",
            "scorer": "DeBERTa",
            "k_star": d.get("kstar"),
            "auc_0v1": d.get("0v1_auc"),
            "auc_1v2": d.get("1v2_auc"),
            "auc_2v3": d.get("2v3_auc"),
            "status": "DONE",
            "conclusion": "success",
            "scorer_notes": "DeBERTa-upper",
        })

rows.sort(key=lambda x: x["exp_id"])

def fmt(v):
    if v is None: return "  -   "
    if isinstance(v, float): return f"{v:.4f}"
    return str(v)

# FINAL TABLE
print(f"{'exp_id':<48} | {'model':<40} | {'scorer':<25} | {'K*':<5} | {'AUC_0v1':<8} | {'AUC_1v2':<8} | {'AUC_2v3':<8} | {'st':<6} | {'concl':<8} | notes")
print("=" * 200)

for r in rows:
    print(f"{r['exp_id']:<48} | {r['model']:<40} | {r['scorer']:<25} | {fmt(r['k_star']):<5} | {fmt(r['auc_0v1']):<8} | {fmt(r['auc_1v2']):<8} | {fmt(r['auc_2v3']):<8} | {r['status'][:6]:<6} | {str(r['conclusion'])[:8]:<8} | {r['scorer_notes']}")

print(f"\n\nTotal rows: {len(rows)}")

# Summary stats
print("\n\n=== PRIORITY EXPERIMENTS SUMMARY ===")
priority_ids = ["exp_018_llama8b_depth", "exp_004_7b_crossscale", "exp_019_mistral7b_depth", 
                "exp_019b_mistral_cross_scorer", "exp_llama8b_10k"]
for pid in priority_ids:
    for r in rows:
        if r["exp_id"] == pid:
            print(f"\n{pid}:")
            print(f"  Model: {r['model']}")
            print(f"  Scorer: {r['scorer']}")
            print(f"  K*={r['k_star']}, AUC 0v1={r['auc_0v1']}, 1v2={r['auc_1v2']}, 2v3={r['auc_2v3']}")
            print(f"  Status: {r['status']}, Conclusion: {r['conclusion']}")
            print(f"  Scorer notes: {r['scorer_notes']}")

PYEOF
